SELECT p.gender, i.icustay_id, o.operator_id, EXTRACT(YEAR FROM i.intime) AS admission_year, COUNT(DISTINCT p.subject_id) AS patient_count, COUNT(DISTINCT pr.procedure_id) AS procedure_count, AVG(i.length_of_stay) AS average_length_of_stay, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS mortality_count FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN operators o ON i.operator_id = o.operator_id JOIN procedureevents pr ON p.subject_id = pr.subject_id AND i.stay_id = pr.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM i.intime) BETWEEN 2017 AND 2018 AND p.anchor_age >= 92 AND p.anchor_age <= 97 AND pr.charttime BETWEEN i.intime AND i.intime + interval '48 hours' AND pr.icd_code IN (SELECT icd_code FROM diagnoses_icd WHERE icd_version = '4') GROUP BY p.gender, i.icustay_id, o.operator_id, admission_year ORDER BY p.gender, i.icustay_id, o.operator_id, admission_year NULLS LAST;